class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        NEG = float('-inf')
        is_target = [False] * n
        for t in targetIndices:
            is_target[t] = True
        dp = [NEG] * (m + 1)
        dp[0] = 0
        for i in range(n):
            t = 1 if is_target[i] else 0
            new = [dp[j] + t if dp[j] != NEG else NEG for j in range(m + 1)]
            for j in range(m):
                if dp[j] != NEG and source[i] == pattern[j]:
                    if dp[j] > new[j + 1]:
                        new[j + 1] = dp[j]
            dp = new
        return int(dp[m])
