class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        NEG = float('-inf')
        removable = [False] * n
        for t in targetIndices:
            removable[t] = True
        dp = [NEG] * (m + 1)
        dp[0] = 0
        for i in range(n):
            ndp = [NEG] * (m + 1)
            c = source[i]
            r = 1 if removable[i] else 0
            for j in range(m + 1):
                if dp[j] == NEG:
                    continue
                # keep or remove without matching
                val = dp[j] + r
                if val > ndp[j]:
                    ndp[j] = val
                # keep and match
                if j < m and pattern[j] == c:
                    if dp[j] > ndp[j + 1]:
                        ndp[j + 1] = dp[j]
            dp = ndp
        return int(dp[m])
