class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        is_target = [False] * n
        for t in targetIndices:
            is_target[t] = True
        INF = float('inf')
        dp = [INF] * (m + 1)
        dp[0] = 0
        for i in range(n):
            c = 1 if is_target[i] else 0
            new = dp[:]
            ch = source[i]
            for j in range(m):
                if dp[j] < INF and pattern[j] == ch:
                    val = dp[j] + c
                    if val < new[j + 1]:
                        new[j + 1] = val
            dp = new
        return len(targetIndices) - dp[m]

