from hypothesis import strategies as st


def _is_subseq(p, s):
    it = iter(s)
    return all(c in it for c in p)


@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    alphabet = draw(st.sampled_from(["ab", "abc", "a"]))
    source = draw(st.text(alphabet=alphabet, min_size=n, max_size=n))
    # pattern: nonempty subsequence of source
    keep = draw(st.lists(st.booleans(), min_size=n, max_size=n))
    pattern = "".join(c for c, k in zip(source, keep) if k)
    if not pattern:
        pattern = source[draw(st.integers(0, n - 1))]
    # targetIndices: nonempty, sorted, distinct, in [0, n-1]
    tmask = draw(st.lists(st.booleans(), min_size=n, max_size=n))
    targets = [i for i, k in enumerate(tmask) if k]
    if not targets:
        targets = [draw(st.integers(0, n - 1))]
    return (
        json.dumps(source) + "\n"
        + json.dumps(pattern) + "\n"
        + json.dumps(targets)
    )


def validate(inp):
    lines = inp.split("\n")
    if len(lines) < 3:
        return False
    try:
        source = json.loads(lines[0])
        pattern = json.loads(lines[1])
        targets = json.loads(lines[2])
    except Exception:
        return False
    if not isinstance(source, str) or not isinstance(pattern, str):
        return False
    if not isinstance(targets, list):
        return False
    n = len(source)
    if not (1 <= n <= 3 * 10 ** 3):
        return False
    if not all(c in "abcdefghijklmnopqrstuvwxyz" for c in source):
        return False
    if not all(c in "abcdefghijklmnopqrstuvwxyz" for c in pattern):
        return False
    if not (1 <= len(pattern) <= n):
        return False
    if not (1 <= len(targets) <= n):
        return False
    if not all(isinstance(x, int) and not isinstance(x, bool) for x in targets):
        return False
    if any(x < 0 or x > n - 1 for x in targets):
        return False
    if any(targets[i] >= targets[i + 1] for i in range(len(targets) - 1)):
        return False
    if not _is_subseq(pattern, source):
        return False
    return True


def ref(inp):
    lines = inp.split("\n")
    source = json.loads(lines[0])
    pattern = json.loads(lines[1])
    targets = json.loads(lines[2])
    best = 0
    m = len(targets)
    # Exhaustive search over every subset of targetIndices to remove.
    for k in range(m + 1):
        for removed in combinations(targets, k):
            rem = set(removed)
            remaining = "".join(
                source[i] for i in range(len(source)) if i not in rem
            )
            if _is_subseq(pattern, remaining):
                best = max(best, k)
    return str(best)
